item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import {aggregateDebtViews, applyRateShock, calculateCovenantHeadroom, calculateLeverage, calculateLiquidityCoverage, calculateProFormaPosition} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	/**
  8	 * Executor of the method `declare-scenarios` (v3, after the second independent review). When
  9	 * management data is missing, the work goes on with declared scenarios: every parameter carries its
 10	 * origin, its rationale and an anchor in a document of the class that origin requires; the executor
 11	 * picks, per role and period, the best origin the register offers. A scenario that declares a lever
 12	 * (shock, haircut, refinancing, rollover) without a registered assumption is blocked, never filled
 13	 * with zero. CFADS is declared per period of the ledger's schedule and never split or repeated by
 14	 * the executor; a CFADS haircut is its own assumption, never derived from the EBITDA haircut. Net
 15	 * debt follows the contractual components; leverage carries the EBITDA's comparability; headroom
 16	 * exists only against an applicable, resolved and comparable limit, otherwise the arithmetic
 17	 * difference is shown as conditioned. Interest enters the service only when the ledger states it.
 18	 * Every derived number carries the assumptions and anchors it rests on.
 19	 */
 20	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 21	const nonEmpty = z.string().trim().min(1);
 22	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 23	const key = z.string().regex(/^[a-z][a-z0-9_.-]*$/);
 24	const moneyUnit = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 25	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand", "ratio"]);
 26	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 27	type Anchor = z.infer<typeof anchorSchema>;
 28	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 29	const UNIT_WORDS: Record<z.infer<typeof moneyUnit>, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};
 30	
 31	export const parameterOriginSchema = z.enum(["authorized_management_data", "public_announcement", "company_history", "versioned_benchmark", "user_range"]);
 32	const originRank: Record<z.infer<typeof parameterOriginSchema>, number> = {authorized_management_data: 0, public_announcement: 1, company_history: 2, versioned_benchmark: 3, user_range: 4};
 33	const originLabel: Record<string, string> = {authorized_management_data: "dado gerencial autorizado", public_announcement: "anúncio público", company_history: "histórico da companhia", versioned_benchmark: "benchmark versionado", user_range: "intervalo declarado pelo usuário"};
 34	export const documentKindSchema = z.enum(["management", "announcement", "itr", "ledger", "benchmark", "user", "indenture", "contract", "disbursement_proof", "other"]);
 35	/** The document classes each origin may cite; an announcement cannot pose as management data and a user range cannot pose as history. */
 36	const ORIGIN_DOCUMENTS: Record<z.infer<typeof parameterOriginSchema>, Array<z.infer<typeof documentKindSchema>>> = {authorized_management_data: ["management"], public_announcement: ["announcement"], company_history: ["itr", "ledger"], versioned_benchmark: ["benchmark"], user_range: ["user"]};
 37	
 38	export const assumptionRoleSchema = z.enum(["cfads", "cfads_haircut", "rate_shock", "ebitda_haircut", "new_debt", "refinanced_debt", "contracted_source", "rollover"]);
 39	const RATIO_ROLES = new Set(["cfads_haircut", "rate_shock", "ebitda_haircut", "rollover"]);
 40	const BOUNDED_ROLES = new Set(["cfads_haircut", "ebitda_haircut", "rollover"]);
 41	
 42	export const assumptionSchema = z.object({
 43	  key,
 44	  role: assumptionRoleSchema,
 45	  /** The period the assumption applies to; null for a scalar that applies everywhere. CFADS and contracted sources are always per period. */
 46	  period: nonEmpty.nullable(),
 47	  value: nonNegative,
 48	  unit: unitSchema,
 49	  origin: parameterOriginSchema,
 50	  rationale: nonEmpty,
 51	  asOf: isoDate,
 52	  anchor: anchorSchema,
 53	  confidence: z.enum(["high", "medium", "low"]),
 54	  /** For a contracted source: the base must hold the contract and the disbursement, each in a document of its class. */
 55	  evidence: z.object({contract: anchorSchema.nullable(), disbursement: anchorSchema.nullable()}).strict().nullable().default(null),
 56	}).strict();
 57	
 58	export const scenarioInputSchema = z.object({
 59	  referenceDate: isoDate,
 60	  unit: moneyUnit,
 61	  /** Where the source states the unit; its note must name it, so a relabelled scale is refused. */
 62	  unitAnchor: anchorSchema.extend({note: nonEmpty}),
 63	  /** The documents of the base with their class; every anchor must name one, and an origin may cite only the classes it is allowed. */
 64	  documents: z.array(z.object({name: nonEmpty, kind: documentKindSchema}).strict()).min(1),
 65	  assumptions: z.array(assumptionSchema).min(1),
 66	  position: z.object({
 67	    perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
 68	    /** Contractual net debt components at the reference date, each with its anchor; a release figure is not a component. */
 69	    components: z.object({
 70	      grossDebt: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 71	      derivativeLiabilities: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 72	      derivativeAssets: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 73	      cashAndEquivalents: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 74	      financialInvestments: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 75	    }).strict(),
 76	    /** The EBITDA the leverage is measured on: twelve months, its definition, how it was derived, and how comparable it is with the covenant definitions. */
 77	    ltmEbitda: z.object({value: nonNegative, months: z.literal(12), definitionKey: nonEmpty, basis: z.enum(["company_opened", "implied_from_reported_index", "derived_proxy"]), comparability: z.enum(["comparable", "conditional", "not_comparable"]), comparabilityReasons: z.array(nonEmpty).default([]), anchor: anchorSchema}).strict().nullable(),
 78	    averageDebtBalance: z.object({value: nonNegative, basis: nonEmpty, anchor: anchorSchema}).strict(),
 79	    baseAnnualRate: z.object({value: nonNegative, basis: nonEmpty, anchor: anchorSchema}).strict(),
 80	  }).strict(),
 81	  /** The covenant the scenarios are read against, from the covenant executor; null when none is resolved. */
 82	  covenant: z.object({instrument: nonEmpty, limit: nonNegative, direction: z.enum(["maximum", "minimum"]), tier: z.object({applicable: z.boolean(), condition: nonEmpty}).strict(), state: z.enum(["resolved", "insufficient_evidence"]), comparability: z.enum(["comparable", "conditional", "not_comparable"]), measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), nextDate: isoDate}).strict(), anchor: anchorSchema}).strict().nullable().default(null),
 83	  /** Debt service by period from the ledger, in the ledger's own periods; interest only when the ledger states it. */
 84	  periods: z.array(z.object({period: nonEmpty, endsAt: isoDate, principal: z.object({value: nonNegative, anchor: anchorSchema}).strict(), interest: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable()}).strict()).min(1),
 85	  scenarios: z.array(z.object({
 86	    id: z.enum(["base", "adverse", "no_rollover"]).or(z.string().regex(/^[a-z][a-z0-9_-]*$/)),
 87	    label: nonEmpty,
 88	    rolloverAllowed: z.boolean(),
 89	    usesRateShock: z.boolean().default(false),
 90	    usesEbitdaHaircut: z.boolean().default(false),
 91	    usesCfadsHaircut: z.boolean().default(false),
 92	    usesRefinancing: z.boolean().default(false),
 93	  }).strict()).min(1),
 94	}).strict().superRefine((input, context) => {
 95	  if (!UNIT_WORDS[input.unit].test(input.unitAnchor.note)) context.addIssue({code: "custom", path: ["unitAnchor"], message: `the unit anchor's note does not name the unit ${input.unit}; a relabelled scale is refused`});
 96	  const documents = new Map(input.documents.map((document) => [document.name, document.kind]));
 97	  const names = new Set<string>();
 98	  input.documents.forEach((document, index) => { if (names.has(document.name)) context.addIssue({code: "custom", path: ["documents", index], message: `duplicate document ${document.name}`}); names.add(document.name); });
 99	  const checkAnchor = (anchor: Anchor, path: (string | number)[]) => { if (!documents.has(anchor.document)) context.addIssue({code: "custom", path, message: `anchor names ${anchor.document}, which is not a document of the base`}); };
100	  checkAnchor(input.unitAnchor, ["unitAnchor"]);
101	  for (const [name, component] of Object.entries(input.position.components)) checkAnchor(component.anchor, ["position", "components", name]);
102	  if (input.position.ltmEbitda) checkAnchor(input.position.ltmEbitda.anchor, ["position", "ltmEbitda"]);
103	  checkAnchor(input.position.averageDebtBalance.anchor, ["position", "averageDebtBalance"]);
104	  checkAnchor(input.position.baseAnnualRate.anchor, ["position", "baseAnnualRate"]);
105	  if (input.covenant) { checkAnchor(input.covenant.anchor, ["covenant"]); if (input.covenant.measurement.nextDate <= input.referenceDate) context.addIssue({code: "custom", path: ["covenant", "measurement"], message: "the next measurement date must follow the reference date"}); }
106	  const periodIds = new Set<string>();
107	  const sorted = [...input.periods].sort((a, b) => compare(a.endsAt, b.endsAt) || compare(a.period, b.period));
108	  sorted.forEach((period, index) => {
109	    if (periodIds.has(period.period)) context.addIssue({code: "custom", path: ["periods", index], message: `duplicate period ${period.period}`});
110	    periodIds.add(period.period);
111	    if (period.endsAt <= input.referenceDate) context.addIssue({code: "custom", path: ["periods", index], message: `period ${period.period} ends on or before the reference date`});
112	    checkAnchor(period.principal.anchor, ["periods", index, "principal"]);
113	    if (period.interest) checkAnchor(period.interest.anchor, ["periods", index, "interest"]);
114	  });
115	  const keys = new Set<string>();
116	  input.assumptions.forEach((assumption, index) => {
117	    if (keys.has(assumption.key)) context.addIssue({code: "custom", path: ["assumptions", index, "key"], message: `duplicate assumption ${assumption.key}`});
118	    keys.add(assumption.key);
119	    checkAnchor(assumption.anchor, ["assumptions", index, "anchor"]);
120	    const kind = documents.get(assumption.anchor.document);
121	    if (kind && !ORIGIN_DOCUMENTS[assumption.origin].includes(kind)) context.addIssue({code: "custom", path: ["assumptions", index, "origin"], message: `${assumption.key}: the origin ${assumption.origin} cannot rest on a ${kind} document; it needs ${ORIGIN_DOCUMENTS[assumption.origin].join(" or ")}`});
122	    if (assumption.role === "contracted_source") {
123	      if (!assumption.evidence || !assumption.evidence.contract || !assumption.evidence.disbursement) context.addIssue({code: "custom", path: ["assumptions", index, "evidence"], message: `${assumption.key}: a contracted source needs its contract and its disbursement in the base; an approval is not a source`});
124	      else {
125	        if (documents.get(assumption.evidence.contract.document) !== "contract") context.addIssue({code: "custom", path: ["assumptions", index, "evidence", "contract"], message: `${assumption.key}: the contract must be a contract document of the base`});
126	        if (documents.get(assumption.evidence.disbursement.document) !== "disbursement_proof") context.addIssue({code: "custom", path: ["assumptions", index, "evidence", "disbursement"], message: `${assumption.key}: the disbursement must be a disbursement proof of the base`});
127	        if (assumption.evidence.contract.document === assumption.evidence.disbursement.document) context.addIssue({code: "custom", path: ["assumptions", index, "evidence"], message: `${assumption.key}: contract and disbursement proof must be two documents`});
128	      }
129	      if (assumption.period === null) context.addIssue({code: "custom", path: ["assumptions", index, "period"], message: `${assumption.key}: a contracted source belongs to one period and is used once`});
130	    }
131	    if (assumption.role === "cfads" && assumption.period === null) context.addIssue({code: "custom", path: ["assumptions", index, "period"], message: `${assumption.key}: CFADS is declared per period of the schedule, never split or repeated by the executor`});
132	    if (RATIO_ROLES.has(assumption.role) && assumption.unit !== "ratio") context.addIssue({code: "custom", path: ["assumptions", index, "unit"], message: `${assumption.key}: a ${assumption.role} is a ratio`});
133	    if (BOUNDED_ROLES.has(assumption.role) && new Decimal(assumption.value).gt(1)) context.addIssue({code: "custom", path: ["assumptions", index, "value"], message: `${assumption.key}: a ${assumption.role} lies between 0 and 1`});
134	    if (!RATIO_ROLES.has(assumption.role) && assumption.unit !== input.unit) context.addIssue({code: "custom", path: ["assumptions", index, "unit"], message: `${assumption.key}: a monetary assumption must be in ${input.unit}`});
135	    if (assumption.period !== null && !periodIds.has(assumption.period)) context.addIssue({code: "custom", path: ["assumptions", index, "period"], message: `${assumption.key} names a period that is not projected`});
136	  });
137	  const ids = new Set<string>();
138	  input.scenarios.forEach((scenario, index) => {
139	    if (ids.has(scenario.id)) context.addIssue({code: "custom", path: ["scenarios", index], message: `duplicate scenario ${scenario.id}`});
140	    ids.add(scenario.id);
141	    if (scenario.id === "adverse" && !scenario.usesRateShock && !scenario.usesEbitdaHaircut && !scenario.usesCfadsHaircut) context.addIssue({code: "custom", path: ["scenarios", index], message: "the adverse scenario must shock the rate or haircut the EBITDA or the CFADS; an adverse scenario with nothing adverse is a label"});
142	    if (scenario.id === "no_rollover" && scenario.rolloverAllowed) context.addIssue({code: "custom", path: ["scenarios", index], message: "the no-rollover scenario cannot allow rollover"});
143	  });
144	  for (const required of ["base", "adverse", "no_rollover"]) if (!ids.has(required)) context.addIssue({code: "custom", path: ["scenarios"], message: `the minimum set needs a ${required} scenario`});
145	});
146	export type ScenarioInput = z.input<typeof scenarioInputSchema>;
147	
148	type Origin = {origin: string; key: string; anchor: Anchor};
149	type Calculation = {id: string; scenario: string; formula: string; operands: Record<string, string>; result: string; unit: string; origins: Origin[]};
150	type Assumption = z.infer<typeof assumptionSchema>;
151	
152	export type ScenarioOutput = {
153	  schema_version: "method.declare-scenarios.v3";
154	  reference_date: string;
155	  unit: string;
156	  state: "declared" | "partial" | "blocked";
157	  block_reasons: string[];
158	  assumption_register: Array<{key: string; role: string; period: string | null; value: string; unit: string; origin: string; origin_rank: number; rationale: string; as_of: string; anchor: Anchor; confidence: string; selected: boolean}>;
159	  scenarios: Array<{
160	    id: string; label: string;
161	    state: "declared" | "partial" | "blocked";
162	    block_reasons: string[];
163	    parameters: Array<{role: string; period: string | null; key: string; value: string; origin: string; rationale: string; anchor: Anchor}>;
164	    results: {
165	      pro_forma: {gross_debt: string; deductible_cash: string; contractual_net_debt: string; leverage: {value: string; ebitda_definition: string; ebitda_basis: string; comparability: string; comparability_reasons: string[]} | null; origins: Origin[]};
166	      headroom: {absolute: string; within_limit: boolean; limit: string; instrument: string; note: string} | null;
167	      headroom_note: string;
168	      interest: {base: string; stressed: string; delta: string; origins: Origin[]} | null;
169	      liquidity: {basis: "principal_only" | "full_debt_service"; rows: Array<{period: string; principal: string; interest: string | null; cfads_declared: string; cfads_used: string; cfads_haircut: string | null; contracted_sources: string; rolled_principal: string; coverage: string | null; closing_cash: string; deficit: string; origins: Origin[]}>} | null;
170	    };
171	    caveat: string;
172	    uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
173	  }>;
174	  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
175	};
176	
177	const d = (value: Decimal.Value) => new Decimal(value);
178	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
179	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
180	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
181	
182	function canonical(input: z.infer<typeof scenarioInputSchema>) {
183	  return {
184	    ...input,
185	    documents: [...input.documents].sort((a, b) => compare(a.name, b.name)),
186	    assumptions: [...input.assumptions].sort((a, b) => compare(a.key, b.key)),
187	    scenarios: [...input.scenarios].sort((a, b) => compare(a.id, b.id)),
188	    periods: [...input.periods].sort((a, b) => compare(a.endsAt, b.endsAt) || compare(a.period, b.period)),
189	    position: {...input.position, ltmEbitda: input.position.ltmEbitda ? {...input.position.ltmEbitda, comparabilityReasons: [...input.position.ltmEbitda.comparabilityReasons].sort(compare)} : null},
190	  };
191	}
192	
193	export function declareScenarios(raw: ScenarioInput): ScenarioOutput {
194	  const input = canonical(scenarioInputSchema.parse(raw));
195	  const calculations: Calculation[] = [];
196	  const selectedKeys = new Set<string>();
197	  const originOf = (assumption: Assumption): Origin => ({origin: originLabel[assumption.origin] ?? assumption.origin, key: assumption.key, anchor: assumption.anchor});
198	  const baseOrigins: Origin[] = [
199	    {origin: "base pública", key: "position.grossDebt", anchor: input.position.components.grossDebt.anchor},
200	    {origin: "base pública", key: "position.cashAndEquivalents", anchor: input.position.components.cashAndEquivalents.anchor},
201	    {origin: "base pública", key: "position.financialInvestments", anchor: input.position.components.financialInvestments.anchor},
202	    {origin: "base pública", key: "position.derivativeLiabilities", anchor: input.position.components.derivativeLiabilities.anchor},
203	    {origin: "base pública", key: "position.derivativeAssets", anchor: input.position.components.derivativeAssets.anchor},
204	  ];
205	  /** The best origin the register offers for a role and period: lowest rank, then highest confidence, then key. */
206	  const pick = (role: Assumption["role"], period: string | null): Assumption | null => {
207	    const candidates = input.assumptions.filter((assumption) => assumption.role === role && (assumption.period === period || (period !== null && assumption.period === null && role !== "cfads")));
208	    const confidenceRank = {high: 0, medium: 1, low: 2};
209	    return [...candidates].sort((a, b) => originRank[a.origin] - originRank[b.origin] || confidenceRank[a.confidence] - confidenceRank[b.confidence] || compare(a.key, b.key))[0] ?? null;
210	  };
211	  const components = input.position.components;
212	  const deductibleCash = d(components.cashAndEquivalents.value).plus(components.financialInvestments.value);
213	  const views = aggregateDebtViews({rows: [{id: "gross_debt", principal: components.grossDebt.value, covenantIncluded: true}, {id: "derivative_liabilities", principal: components.derivativeLiabilities.value, covenantIncluded: true}], cash: deductibleCash.plus(components.derivativeAssets.value)});
214	  calculations.push({id: "financial.debt_views:contractual", scenario: "all", formula: "grossDebt + derivativeLiabilities - cashAndEquivalents - financialInvestments - derivativeAssets", operands: {grossDebt: components.grossDebt.value, derivativeLiabilities: components.derivativeLiabilities.value, cashAndEquivalents: components.cashAndEquivalents.value, financialInvestments: components.financialInvestments.value, derivativeAssets: components.derivativeAssets.value}, result: views.netFinancialDebt, unit: input.unit, origins: baseOrigins});
215	  const interestDeclared = input.periods.every((period) => period.interest !== null);
216	
217	  const scenarios = input.scenarios.map((scenario): ScenarioOutput["scenarios"][number] => {
218	    const parameters: ScenarioOutput["scenarios"][number]["parameters"] = [];
219	    const uncovered: ScenarioOutput["scenarios"][number]["uncovered_terms"] = [];
220	    const blocks: string[] = [];
221	    const use = (role: Assumption["role"], period: string | null): Assumption | null => {
222	      const assumption = pick(role, period);
223	      if (assumption) { selectedKeys.add(assumption.key); parameters.push({role, period, key: assumption.key, value: out(d(assumption.value)), origin: assumption.origin, rationale: assumption.rationale, anchor: assumption.anchor}); }
224	      return assumption;
225	    };
226	    const originsOf = (...items: Array<Assumption | null>) => items.filter((item): item is Assumption => item !== null).map(originOf).sort((a, b) => compare(a.key, b.key));
227	    const rollover = scenario.rolloverAllowed ? use("rollover", null) : null;
228	    if (scenario.rolloverAllowed && !rollover) blocks.push("the scenario assumes rollover of maturing principal but no rollover assumption is registered with an origin; rollover is not assumed by default");
229	    const shock = scenario.usesRateShock ? use("rate_shock", null) : null;
230	    if (scenario.usesRateShock && !shock) blocks.push("the scenario declares a rate shock but none is registered; a shock of zero is not a shock");
231	    const haircut = scenario.usesEbitdaHaircut ? use("ebitda_haircut", null) : null;
232	    if (scenario.usesEbitdaHaircut && !haircut) blocks.push("the scenario declares an EBITDA haircut but none is registered; the haircut is not filled with zero");
233	    const cfadsHaircut = scenario.usesCfadsHaircut ? use("cfads_haircut", null) : null;
234	    if (scenario.usesCfadsHaircut && !cfadsHaircut) blocks.push("the scenario declares a CFADS haircut but none is registered; the EBITDA haircut is never applied to CFADS in its place");
235	    const newDebt = scenario.usesRefinancing ? use("new_debt", null) : null;
236	    const refinanced = scenario.usesRefinancing ? use("refinanced_debt", null) : null;
237	    if (scenario.usesRefinancing && (!newDebt || !refinanced)) blocks.push("a refinancing is new debt replacing old debt; both amounts must be registered, and a subtraction alone is not a refinancing");
238	    const caveatFor = (state: string) => {
239	      const used = parameters.map((parameter) => `${originLabel[parameter.origin] ?? parameter.origin} (${parameter.key}: ${parameter.rationale})`);
240	      return `Cenário ${scenario.label} (${state}), declarado a partir de ${used.join("; ") || "nenhum parâmetro próprio"}; não é guidance da companhia e não afirma o que a companhia fará; cada número acima carrega as premissas e âncoras de que depende.`;
241	    };
242	    const headroomNote = (leverage: string | null): string => {
243	      if (!input.covenant) return "no covenant limit received; no headroom";
244	      if (!leverage) return "no leverage measured; no headroom";
245	      const reasons: string[] = [];
246	      if (input.covenant.state !== "resolved") reasons.push(`the limit of ${input.covenant.instrument} is ${input.covenant.state}`);
247	      if (!input.covenant.tier.applicable) reasons.push(`the ${input.covenant.limit}x tier is not applicable (${input.covenant.tier.condition})`);
248	      if (input.covenant.comparability !== "comparable") reasons.push(`the covenant comparison is ${input.covenant.comparability}`);
249	      if (input.position.ltmEbitda && input.position.ltmEbitda.comparability !== "comparable") reasons.push(`the EBITDA is ${input.position.ltmEbitda.comparability} with the covenant definition`);
250	      if (reasons.length === 0) return `headroom measured against the ${input.covenant.limit}x tier of ${input.covenant.instrument}, as a scenario reading before the measurement of ${input.covenant.measurement.nextDate}`;
251	      const arithmetic = input.covenant.direction === "maximum" ? d(input.covenant.limit).minus(leverage) : d(leverage).minus(input.covenant.limit);
252	      return `no headroom: ${reasons.join("; ")}. The arithmetic difference against ${input.covenant.limit}x is ${out(arithmetic)}x and is conditioned, not a headroom`;
253	    };
254	    if (blocks.length > 0) {
255	      for (const block of blocks) uncovered.push({id: `lever:${scenario.id}`, state: "insufficient_evidence", reason: block});
